<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationMetadataJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationMetadataJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withMetadataJson,
 * getMetadataJson/metadataJson accessors, and isMetadataJsonChanged with/without original.
 */
class UserInvitationMetadataJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMetadataJson creates a new instance with the MetadataJson set
     * from a string value, and getMetadataJson returns the primitive string.
     */
    public function testWithMetadataJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationMetadataJsonAccessorUnitTest();

        // Act
        $result = $holder->withMetadataJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getMetadataJson());
    }
    /**
     * Asserts that withmetadataJson has access to the value object
     * from a string value, and getMetadataJson returns the primitive string.
     */
    public function testWithMetadataJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationMetadataJsonAccessorUnitTest();

        // Act
        $result = $holder->withMetadataJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->metadataJson()->value());
    }
    public function testChangedMetadataJson(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationMetadataJsonAccessorUnitTest();
        $original = $holder->withMetadataJson('one');
        $same = $holder->withMetadataJson('one');
        $modified = $holder->withMetadataJson('other');

        // Act
        $unchanged = $holder->isMetadataJsonChanged();
        $withSame = $original->isMetadataJsonChanged($same);
        $withDiferent = $original->isMetadataJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationMetadataJsonAccessorUnitTest
{
    use UserInvitationMetadataJsonAccessor;
}
